const input = $input.first().json;
const body = input.body ?? input;

const customerMessage = body.message ?? body.query ?? body.chatInput;
const customerEmail = body.customer_email ?? body.email ?? "";
const customerName = body.customer_name ?? body.name ?? "";

if (typeof customerMessage !== "string" || !customerMessage.trim()) {
  throw new Error("Customer message is required.");
}

return [{
  json: {
    customer_message: customerMessage.trim(),
    customer_name: String(customerName).trim(),
    customer_email: String(customerEmail).trim(),
    received_at: new Date().toISOString(),
    source: "webhook"
  }
}];

const result = $input.first().json;

let raw =
  result.output?.[0]?.content?.[0]?.text ??
  result.message?.content ??
  result.text ??
  result.content ??
  result;

if (typeof raw === "string") {
  raw = raw.replace(/^```json\s*/i, "").replace(/\s*```$/, "");
  try {
    raw = JSON.parse(raw);
  } catch {
    throw new Error("Classifier output is not valid JSON.");
  }
}

const allowed = new Set([
  "knowledge",
  "check_availability",
  "book_appointment",
  "reschedule_appointment",
  "cancel_appointment",
  "human_support"
]);

if (!Array.isArray(raw.intents)) {
  throw new Error("Classifier must return an intents array.");
}

const intents = [...new Set(raw.intents.filter(x => allowed.has(x)))];

if (!intents.length) {
  throw new Error("No supported intent detected.");
}

const customer = $("Validate Customer Input").first().json;

// Preserve the original appointment details separately.
// These fields must be extracted by the classifier.
const originalAppointmentDate = raw.original_appointment_date ?? null;
const originalStartTime = raw.original_start_time ?? null;

return [{
  json: {
    ...raw,
    original_appointment_date: originalAppointmentDate,
    original_start_time: originalStartTime,
    intents,
    primary_intent: intents.includes("human_support")
      ? "human_support"
      : intents[0],
    customer_message: customer.customer_message,
    customer_name: raw.customer_name || customer.customer_name || "",
    customer_email: raw.customer_email || customer.customer_email || "",
    requires_human: Boolean(raw.requires_human) || intents.includes("human_support")
  }
}];

const result = $input.first().json;

const answer =
  result.output?.[0]?.content?.[0]?.text ??
  result.message?.content ??
  result.text ??
  result.response ??
  result.content;

if (typeof answer !== "string" || !answer.trim()) {
  throw new Error(
    "Knowledge answer was not found. Inspect Generate Knowledge Answer output and update the extraction path."
  );
}

return [{
  json: {
    intent: "knowledge",
    answer: answer.trim(),
    status: "success"
  }
}];

const docs = $input.all();

const context = docs.map((item, i) => {
  const data = item.json;
  const text =
    data.pageContent ??
    data.document?.pageContent ??
    data.text ??
    data.content ??
    "";

  return text ? `Document ${i + 1}:\n${text}` : "";
}).filter(Boolean).join("\n\n");

if (!context) {
  throw new Error(
    "No document text returned. Check Retrieve Business Knowledge output."
  );
}

const customer = $('Validate Customer Input').first().json;

return [{
  json: {
    retrieved_context: context,
    customer_message: customer.customer_message,
    customer_name: customer.customer_name,
    customer_email: customer.customer_email
  }
}];

